(function() {
  "use strict";

  function deepMerge(target, source) {
    var out = Object.assign({}, target);
    if (source && typeof source === "object") {
      Object.keys(source).forEach(function(key) {
        if (source[key] && typeof source[key] === "object" && !Array.isArray(source[key])) {
          out[key] = deepMerge(target[key] || {}, source[key]);
        } else if (source[key] !== undefined) {
          out[key] = source[key];
        }
      });
    }
    return out;
  }

  function getCookie(name) {
    var cname = name + "=";
    var decoded = decodeURIComponent(document.cookie);
    var ca = decoded.split(";");
    for (var i = 0; i < ca.length; i++) {
      var c = ca[i].trim();
      if (c.indexOf(cname) === 0) return c.substring(cname.length, c.length);
    }
    return "";
  }

  function setCookie(cname, cvalue, minutes) {
    var d = new Date();
    d.setTime(d.getTime() + (minutes * 60 * 1000));
    var expires = "expires=" + d.toUTCString();
    document.cookie = cname + "=" + cvalue + ";" + expires + ";path=/";
  }

  function getDayAndTime(tz) {
    var now = new Date();
    var options = {
      weekday: "long",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
      hour12: false
    };
    if (tz) {
      try {
        options.timeZone = tz;
      } catch (e) {
        // Fallback to local system time zone if invalid
      }
    }
    var formatter = new Intl.DateTimeFormat("en-US", options);
    var parts = formatter.formatToParts(now);
    var day = "", hour = "00", minute = "00", second = "00";
    for (var i = 0; i < parts.length; i++) {
      if (parts[i].type === "weekday") day = parts[i].value.toLowerCase();
      if (parts[i].type === "hour") hour = parts[i].value;
      if (parts[i].type === "minute") minute = parts[i].value;
      if (parts[i].type === "second") second = parts[i].value;
    }
    if (hour === "24") hour = "00";
    var timeSec = parseInt(hour, 10) * 3600 + parseInt(minute, 10) * 60 + parseInt(second, 10);
    return { day: day, timeSec: timeSec };
  }

  function isWithinRange(rangeStr, currentSec) {
    if (!rangeStr || typeof rangeStr !== "string" || rangeStr.indexOf("-") === -1) return false;
    var parts = rangeStr.split("-");
    var startParts = parts[0].trim().split(":");
    var endParts = parts[1].trim().split(":");
    var startSec = parseInt(startParts[0], 10) * 3600 + parseInt(startParts[1] || "0", 10) * 60;
    var endSec = parseInt(endParts[0], 10) * 3600 + parseInt(endParts[1] || "0", 10) * 60 + 59;
    return currentSec >= startSec && currentSec <= endSec;
  }

  function getPluginBaseScriptDir() {
    var script = document.currentScript;
    if (script && script.src) {
      return script.src.substring(0, script.src.lastIndexOf("/") + 1);
    }
    return "";
  }

  window.easyChatSupport = function(target, options) {
    var elements = typeof target === "string" ? document.querySelectorAll(target) : (target.length ? target : [target]);
    if (!elements || elements.length === 0) return;

    var defaults = {
      button: {
        position: "right",
        style: 1,
        src: '<i class="fab fa-whatsapp"></i>',
        backgroundColor: "#26c281",
        effect: 1,
        notificationNumber: "1",
        speechBubble: "How can we help you?",
        pulseEffect: true,
        text: {
          title: "Need help? Chat with us",
          description: "Customer Support",
          online: "I'm Online",
          offline: "I will be back soon"
        },
        link: { desktop: false, mobile: false },
        onlineDay: {
          sunday: false, monday: false, tuesday: false,
          wednesday: false, thursday: false, friday: false, saturday: false
        },
        delay: true
      },
      popup: {
        automaticOpen: false,
        outsideClickClosePopup: true,
        effect: 1,
        header: {
          backgroundColor: "#26c281",
          title: "Need help? Chat with us",
          description: "Click one of our representatives below"
        },
        persons: [],
        personsSettings: {
          avatar: {
            src: '<i class="fab fa-whatsapp"></i>',
            backgroundColor: "#26c281",
            onlineCircle: true
          },
          text: {
            title: "Need Help?",
            description: "Customer Support",
            online: "I'm Online",
            offline: "I will be back soon",
            message: false,
            textbox: false,
            button: "Start Chat"
          },
          link: { desktop: false, mobile: false },
          onlineDay: {
            sunday: false, monday: false, tuesday: false,
            wednesday: false, thursday: false, friday: false, saturday: false
          }
        }
      },
      sound: true,
      changeBrowserTitle: "New Message!",
      cookie: false,
      timezone: false,
      onLoad: function() {},
      onClick: function() {},
      onPopupOpen: function() {},
      onPopupClose: function() {}
    };

    var p = deepMerge(defaults, options || {});
    var currentTimeInfo = getDayAndTime(p.timezone);
    var baseDir = getPluginBaseScriptDir();

    Array.prototype.forEach.call(elements, function(el) {
      if (getCookie("easyChatSupport") === "true") {
        p.button.pulseEffect = false;
        p.button.notificationNumber = false;
        p.button.speechBubble = false;
        p.button.delay = false;
        p.popup.automaticOpen = false;
        p.sound = false;
        p.changeBrowserTitle = false;
      }

      if (typeof p.onLoad === "function") {
        p.onLoad.call(el);
      }

      if (p.button.position !== "right" && p.button.position !== "left") {
        p.button.speechBubble = false;
      }

      el.classList.add("easy-chat-support", "easy-chat-support-" + p.button.style);

      var btnEl = document.createElement("div");
      btnEl.className = "easy-button";
      el.insertBefore(btnEl, el.firstChild);

      if (p.button.position === "right" || p.button.position === "left") {
        el.classList.add("easy-fixed");
        el.classList.add(p.button.position === "right" ? "easy-right" : "easy-left");

        if (p.button.delay !== false) {
          if ([2, 4, 5, 7].indexOf(parseInt(p.button.effect, 10)) !== -1) {
            p.button.effect = p.button.effect + (p.button.position === "right" ? "__1" : "__2");
          }
          el.classList.add("easy-chat-support-show");
          btnEl.classList.add("animate__animated", "animate__" + p.button.effect);
          setTimeout(function() {
            btnEl.classList.remove("animate__animated", "animate__" + p.button.effect);
          }, 1000);
        } else {
          el.classList.add("easy-chat-support-show");
        }
      } else {
        el.classList.add("easy-chat-support-show");
      }

      var isOnline = true;
      if (p.button.link.desktop !== false || p.button.link.mobile !== false) {
        var daySchedule = p.button.onlineDay[currentTimeInfo.day];
        if (!daySchedule || !isWithinRange(daySchedule, currentTimeInfo.timeSec)) {
          isOnline = false;
        }
      } else if (p.popup.persons.length === 0) {
        isOnline = false;
      }

      btnEl.style.backgroundColor = p.button.backgroundColor;

      var avatarEl = document.createElement("div");
      avatarEl.className = "easy-button-person-avatar";
      avatarEl.innerHTML = p.button.src;
      btnEl.appendChild(avatarEl);

      if (p.button.style === 6 || p.button.style === 7) {
        avatarEl.style.backgroundColor = p.button.backgroundColor;
      }

      if (p.button.style === 3 || p.button.style === 5) {
        var contentEl = document.createElement("div");
        contentEl.className = "easy-button-content";
        contentEl.innerHTML = '<div class="easy-button-content-title">' + (p.button.text.title || '') + '</div>';
        btnEl.appendChild(contentEl);
      } else if ([2, 4, 6, 7].indexOf(p.button.style) !== -1) {
        var contentEl2 = document.createElement("div");
        contentEl2.className = "easy-button-content";
        contentEl2.innerHTML = '<div class="easy-button-content-title">' + (p.button.text.title || '') + '</div>';
        btnEl.appendChild(contentEl2);

        if (p.button.text.description) {
          var descEl = document.createElement("div");
          descEl.className = "easy-button-content-description";
          descEl.textContent = p.button.text.description;
          contentEl2.appendChild(descEl);
        }

        var statusText = isOnline ? p.button.text.online : p.button.text.offline;
        if (statusText) {
          var statusEl = document.createElement("div");
          statusEl.className = "easy-button-content-online-offline-text";
          statusEl.textContent = statusText;
          contentEl2.appendChild(statusEl);
        }
      }

      if (p.button.src.indexOf("img") !== -1) {
        btnEl.classList.add("easy-button-image");
      }
      if (!isOnline) {
        btnEl.classList.add("easy-button-offline");
      }

      function togglePopup() {
        el.classList.toggle("easy-popup-show");
      }

      // Standalone button click logic
      if ((p.button.link.desktop !== false || p.button.link.mobile !== false) && isOnline) {
        btnEl.addEventListener("click", function() {
          var isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
          var href = isMobile && p.button.link.mobile ? p.button.link.mobile : p.button.link.desktop;
          window.open(href, "_blank");
          if (typeof p.onClick === "function") p.onClick.call(el);
        });
      }

      // Popup initialization
      if (!p.button.link.desktop && !p.button.link.mobile && p.popup.persons.length > 0 && (p.button.position === "right" || p.button.position === "left")) {
        if (p.popup.outsideClickClosePopup) {
          document.addEventListener("click", function(e) {
            if (el.classList.contains("easy-popup-show") && !el.contains(e.target)) {
              togglePopup();
              if (typeof p.onPopupClose === "function") p.onPopupClose.call(el);
            }
          });
        }

        btnEl.addEventListener("click", function(e) {
          e.stopPropagation();
          togglePopup();
          if (el.classList.contains("easy-popup-show")) {
            if (typeof p.onPopupOpen === "function") p.onPopupOpen.call(el);
          } else {
            if (typeof p.onPopupClose === "function") p.onPopupClose.call(el);
          }
        });

        if ([2, 10, 12].indexOf(parseInt(p.popup.effect, 10)) !== -1) {
          p.popup.effect = p.popup.effect + (p.button.position === "right" ? "__1" : "__2");
        }

        var popupEl = document.createElement("div");
        popupEl.className = "easy-popup animate__popup__" + p.popup.effect;
        el.insertBefore(popupEl, el.firstChild);

        if (p.popup.automaticOpen) {
          var delayMs = p.button.delay ? 900 : 200;
          setTimeout(function() {
            togglePopup();
            if (typeof p.onPopupOpen === "function") p.onPopupOpen.call(el);
          }, delayMs);
        }

        var headerEl = document.createElement("div");
        headerEl.className = "easy-popup-header";
        headerEl.style.backgroundColor = p.popup.header.backgroundColor;
        headerEl.innerHTML = '<span class="easy-popup-close"></span>' +
          '<div class="easy-popup-header-title">' + (p.popup.header.title || 'Need Help? Chat with us') + '</div>' +
          (p.popup.header.description ? '<div class="easy-popup-header-description">' + p.popup.header.description + '</div>' : '');
        popupEl.appendChild(headerEl);

        headerEl.querySelector(".easy-popup-close").addEventListener("click", function(e) {
          e.stopPropagation();
          togglePopup();
          if (typeof p.onPopupClose === "function") p.onPopupClose.call(el);
        });

        var areaEl = document.createElement("div");
        areaEl.className = "easy-popup-area";
        var personsContainer = document.createElement("div");
        personsContainer.className = "easy-popup-persons";
        areaEl.appendChild(personsContainer);
        popupEl.appendChild(areaEl);

        if (p.popup.persons.length > 5) {
          popupEl.classList.add("easy-popup-small");
        }

        p.popup.persons.forEach(function(personRaw, u) {
          var person = deepMerge(p.popup.personsSettings, personRaw);
          var daySched = person.onlineDay[currentTimeInfo.day];
          var personOnline = true;
          if (!daySched || !isWithinRange(daySched, currentTimeInfo.timeSec)) {
            personOnline = false;
          }

          var personEl = document.createElement("div");
          personEl.className = "easy-popup-person";
          personEl.setAttribute("data-id", u);

          var pAvatarEl = document.createElement("div");
          pAvatarEl.className = "easy-popup-person-avatar";
          pAvatarEl.style.backgroundColor = person.avatar.backgroundColor;
          pAvatarEl.innerHTML = person.avatar.src;
          personEl.appendChild(pAvatarEl);

          var pContentEl = document.createElement("div");
          pContentEl.className = "easy-popup-person-content";
          pContentEl.innerHTML = '<div class="easy-popup-person-title">' + (person.text.title || 'Need Help?') + '</div>';
          if (person.text.description) {
            pContentEl.innerHTML += '<div class="easy-popup-person-description">' + person.text.description + '</div>';
          }

          if (personOnline) {
            if (person.avatar.onlineCircle) {
              var circle = document.createElement("div");
              circle.className = "easy-popup-person-avatar-status";
              pAvatarEl.appendChild(circle);
            }
            if (person.text.online) {
              var onText = document.createElement("div");
              onText.className = "easy-popup-person-online-offline-text";
              onText.style.backgroundColor = p.popup.header.backgroundColor;
              onText.textContent = person.text.online;
              pContentEl.appendChild(onText);
            }
          } else {
            personEl.classList.add("easy-popup-person-offline");
            if (person.text.offline) {
              var offText = document.createElement("div");
              offText.className = "easy-popup-person-online-offline-text";
              offText.textContent = person.text.offline;
              pContentEl.appendChild(offText);
            }
          }

          personEl.appendChild(pContentEl);

          // Single person specialization
          if (p.popup.persons.length === 1) {
            popupEl.classList.add("easy-popup-single");
            var oldTitle = headerEl.querySelector(".easy-popup-header-title");
            if (oldTitle) oldTitle.remove();
            var oldDesc = headerEl.querySelector(".easy-popup-header-description");
            if (oldDesc) oldDesc.remove();

            personEl.style.backgroundColor = p.popup.header.backgroundColor;
            pAvatarEl.style.backgroundColor = "#ffffff";
            var icon = pAvatarEl.querySelector("i");
            if (icon) icon.style.color = p.popup.header.backgroundColor;
            var curStatusText = pContentEl.querySelector(".easy-popup-person-online-offline-text");
            if (curStatusText) curStatusText.remove();

            var chatArea = document.createElement("div");
            chatArea.className = "easy-popup-start-chat";

            if (person.text.message) {
              personEl.classList.add("easy-popup-person-message");
              chatArea.innerHTML += '<div class="easy-popup-start-chat-message"><div>' + person.text.message + '</div></div>';
            }

            if (person.text.textbox) {
              chatArea.innerHTML += '<div class="easy-popup-start-chat-textbox"><input type="text" placeholder="' + person.text.textbox + '" autocomplete="off"><i class="fa fa-play"></i></div>';
              var sendChat = function() {
                var isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
                var link = isMobile && person.link.mobile ? person.link.mobile : person.link.desktop;
                if (!link) return;
                var input = chatArea.querySelector('input[type="text"]');
                var val = input ? encodeURIComponent(input.value) : "";
                if (link.indexOf("text=") !== -1) {
                  link = link.split("text=")[0];
                }
                link = link + (link.indexOf("?") === -1 ? "?" : "&") + "text=" + val;
                window.open(link, "_blank");
              };

              var iconSend = chatArea.querySelector("i");
              if (iconSend) iconSend.addEventListener("click", sendChat);

              var inputField = chatArea.querySelector('input[type="text"]');
              if (inputField) {
                inputField.addEventListener("keyup", function(e) {
                  if (e.keyCode === 13) sendChat();
                });
              }
            } else {
              chatArea.innerHTML += '<div class="easy-popup-start-chat-button"><span>' + (person.text.button || "Start Chat") + '</span></div>';
              var btnStart = chatArea.querySelector(".easy-popup-start-chat-button");
              if (btnStart) {
                btnStart.style.backgroundColor = p.popup.header.backgroundColor;
                btnStart.addEventListener("click", function() {
                  var isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
                  var link = isMobile && person.link.mobile ? person.link.mobile : person.link.desktop;
                  if (link) window.open(link, "_blank");
                });
              }
            }
            personEl.appendChild(chatArea);

            if (!personOnline) {
              popupEl.remove();
              btnEl.classList.add("easy-button-offline");
              var offlineEl = btnEl.querySelector(".easy-button-content-online-offline-text");
              if (offlineEl) {
                if (p.button.text.offline) {
                  offlineEl.textContent = p.button.text.offline;
                } else {
                  offlineEl.remove();
                }
              }
              isOnline = false;
            }
          } else {
            // Multi-person click
            personEl.addEventListener("click", function() {
              var isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
              var link = isMobile && person.link.mobile ? person.link.mobile : person.link.desktop;
              if (link) window.open(link, "_blank");
            });
          }

          personsContainer.appendChild(personEl);
        });
      }

      // Visual effects & badges
      if (p.button.pulseEffect && isOnline && p.button.style === 1) {
        var pulse1 = document.createElement("div");
        pulse1.className = "easy-pulse";
        pulse1.style.backgroundColor = p.button.backgroundColor;
        var pulse2 = document.createElement("div");
        pulse2.className = "easy-pulse";
        pulse2.style.backgroundColor = p.button.backgroundColor;
        btnEl.appendChild(pulse1);
        btnEl.appendChild(pulse2);
      }

      if (p.button.notificationNumber && isOnline) {
        var notifyEl = document.createElement("div");
        notifyEl.className = "easy-notify";
        notifyEl.innerHTML = '<div class="easy-notify-circle"></div>';
        btnEl.appendChild(notifyEl);

        setTimeout(function() {
          var circle = notifyEl.querySelector(".easy-notify-circle");
          if (!circle) return;
          circle.classList.add("easy-notify-circle-show", "easy-bounce");
          circle.textContent = p.button.notificationNumber;
          setInterval(function() {
            circle.classList.toggle("easy-bounce");
          }, 2000);
        }, 4000);
      }

      if (p.button.speechBubble && isOnline) {
        var bubbleEl = document.createElement("div");
        bubbleEl.className = "easy-speech-bubble";
        bubbleEl.innerHTML = '<span class="easy-speech-bubble-close"></span><div class="easy-speech-bubble-text"></div>';
        el.insertBefore(bubbleEl, el.firstChild);

        setTimeout(function() {
          bubbleEl.classList.add("easy-speech-bubble-show");
          var textEl = bubbleEl.querySelector(".easy-speech-bubble-text");
          textEl.innerHTML = '<div class="easy-speech-bubble-typing"><div></div><div></div><div></div></div>';

          setTimeout(function() {
            var closeBtn = bubbleEl.querySelector(".easy-speech-bubble-close");
            if (closeBtn) closeBtn.classList.add("easy-speech-bubble-close-show");
            textEl.innerHTML = p.button.speechBubble;
          }, 3000);
        }, 1000);

        bubbleEl.querySelector(".easy-speech-bubble-close").addEventListener("click", function(e) {
          e.stopPropagation();
          bubbleEl.classList.remove("easy-speech-bubble-show");
        });
      }

      // Sound notification
      if (p.sound !== false && isOnline) {
        var soundUrl = p.sound === true ? baseDir + "../sound/notification.mp3" : p.sound;
        setTimeout(function() {
          var existingAudio = document.getElementById("easySound");
          if (existingAudio) existingAudio.remove();

          var audio = document.createElement("audio");
          audio.id = "easySound";
          audio.src = soundUrl;
          el.appendChild(audio);
          var playPromise = audio.play();
          if (playPromise !== undefined) {
            playPromise.then(function() {}).catch(function() {});
          }
        }, 4000);
      }

      // Browser Tab title alternation
      if (p.changeBrowserTitle !== false && isOnline) {
        var favIconTag = document.querySelector('link[rel="shortcut icon"]') || document.querySelector('link[rel="icon"]');
        var originalFavicon = favIconTag ? favIconTag.getAttribute("href") : null;
        var altFavicon = baseDir + "assets/img/browser-title-number.png";
        var originalTitle = document.title;
        var altTitle = p.changeBrowserTitle;
        var titleInterval = null;
        var toggle = false;

        window.addEventListener("blur", function() {
          document.title = altTitle;
          if (favIconTag && altFavicon) favIconTag.setAttribute("href", altFavicon);

          titleInterval = setInterval(function() {
            document.title = toggle ? originalTitle : altTitle;
            if (favIconTag) favIconTag.setAttribute("href", toggle ? originalFavicon : altFavicon);
            toggle = !toggle;
          }, 1000);
        });

        window.addEventListener("focus", function() {
          clearInterval(titleInterval);
          if (favIconTag && originalFavicon) favIconTag.setAttribute("href", originalFavicon);
          document.title = originalTitle;
        });
      }

      if (p.cookie !== false && isOnline && getCookie("easyChatSupport") !== "true") {
        setCookie("easyChatSupport", "true", parseInt(p.cookie, 10) * 60);
      }
    });
  };
})();